72	export function loadConfig(configPath: string): OpenSpecConfig {
73	  if (!existsSync(configPath)) {
74	    throw new ConfigError(`Config file not found: ${configPath}`);
75	  }
76	
77	  let raw: unknown;
78	  try {
79	    const content = readFileSync(configPath, "utf-8");
80	    raw = yaml.load(content);
81	  } catch (err) {
82	    throw new ConfigError(
83	      `Failed to parse config YAML: ${err instanceof Error ? err.message : String(err)}`
84	    );
85	  }
86	
87	  if (raw === null || raw === undefined || typeof raw !== "object") {
88	    throw new ConfigError("Config file is empty or not a YAML mapping");
89	  }
90	
91	  return validateConfig(raw as RawConfig);
92	}
