94	/**
95	 * Load config from a working directory (convenience wrapper).
96	 */
97	export function loadConfigFromDir(cwd: string): OpenSpecConfig {
98	  const configPath = findConfigPath(cwd);
99	  if (!configPath) {
100	    throw new ConfigError(
101	      `No openspec/config.yaml found in ${cwd}. Run 'corgispec init' to set up.`
102	    );
103	  }
104	  return loadConfig(configPath);
105	}
