402	function detectManagedFileModifications(
403	  target: string,
404	  manifestPath: string | undefined
405	): string[] {
406	  if (!manifestPath || !existsSync(manifestPath)) {
407	    return [];
408	  }
409	
410	  const manifest = JSON.parse(readFileSync(manifestPath, "utf-8")) as InstallManifest;
411	  const modified: string[] = [];
412	  for (const [relativePath, entry] of Object.entries(manifest.files ?? {})) {
413	    const targetFile = resolve(target, relativePath);
414	    if (!existsSync(targetFile)) {
415	      modified.push(relativePath);
416	      continue;
417	    }
418	
419	    const currentHash = sha256File(targetFile);
420	    if (entry.sha256 && currentHash !== entry.sha256) {
421	      modified.push(relativePath);
422	    }
423	  }
424	  return modified;
425	}
