474	function resolveBootstrapMode(requested: BootstrapMode, targetState: ReturnType<typeof classifyTargetState>["kind"]): BootstrapResult["mode"] {
475	  if (requested === "fresh") return "fresh";
476	  if (requested === "update") return "update";
477	  if (requested === "legacy") return "legacy";
478	  if (requested === "verify") return "verify";
479	
480	  switch (targetState) {
481	    case "managed-update":
482	      return "update";
483	    case "legacy":
484	      return "legacy";
485	    default:
486	      return "fresh";
487	  }
488	}
